import type { MetadataRoute } from 'next';
import { SITE } from '@/lib/siteConfig';

/**
 * GET /manifest.webmanifest — linked from every page automatically.
 *
 * What a phone uses when someone adds the site to their home screen: the name
 * under the icon, the icon itself, and the colour of the splash screen. The PNG
 * icons are generated by `scripts/generate-brand-assets.mjs`; `theme_color`
 * matches `viewport.themeColor` in the root layout.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: SITE.name,
    short_name: SITE.shortName,
    description: SITE.description,
    lang: 'bs',
    start_url: '/',
    display: 'standalone',
    background_color: '#ffffff',
    theme_color: '#2f5bea',
    icons: [
      { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
